  INDEX idx_spend_limit_target_app_user_id (target_app_user_id) WHERE target_app_user_id IS NOT NULL,
  INDEX idx_spend_limit_licence_id (licence_id) WHERE licence_id IS NOT NULL,
  INDEX idx_spend_limit_currency_id (currency_id)
);
