CREATE TABLE IF NOT EXISTS subscription (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  organisation_id UUID NOT NULL,
  account_id UUID NOT NULL,
  licence_id UUID NOT NULL,
  plan_version_id UUID NOT NULL,
  subscription_status_id UUID NOT NULL,
  renewal_mode_id UUID NOT NULL,
  billing_interval_id UUID NOT NULL,
  currency_id UUID NOT NULL,
  recurring_amount DECIMAL(18,4) NOT NULL,
  payment_method_token_id UUID,
  started_at TIMESTAMPTZ NOT NULL,
  trial_ends_at TIMESTAMPTZ,
  cancel_at_period_end BOOL NOT NULL DEFAULT false,
  ended_at TIMESTAMPTZ,
  CONSTRAINT pk_subscription PRIMARY KEY (id),
  CONSTRAINT uq_subscription_id_licence UNIQUE (id, licence_id),
  CONSTRAINT ck_subscription_recurring_nonneg CHECK (recurring_amount >= 0),
  CONSTRAINT ck_subscription_ended_after_start CHECK (ended_at IS NULL OR ended_at >= started_at),
  CONSTRAINT fk_subscription_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_subscription_account_id FOREIGN KEY (account_id) REFERENCES account (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_subscription_plan_version_id FOREIGN KEY (plan_version_id) REFERENCES plan_version (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_subscription_subscription_status_id FOREIGN KEY (subscription_status_id) REFERENCES subscription_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_subscription_renewal_mode_id FOREIGN KEY (renewal_mode_id) REFERENCES renewal_mode (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_subscription_billing_interval_id FOREIGN KEY (billing_interval_id) REFERENCES billing_interval (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_subscription_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_subscription_payment_method_token_id FOREIGN KEY (payment_method_token_id) REFERENCES payment_method_token (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_subscription_licence_id_live (licence_id) WHERE ended_at IS NULL AND deleted_at IS NULL,
  INDEX idx_subscription_organisation_id_status (organisation_id, subscription_status_id),
  INDEX idx_subscription_account_id (account_id),
  INDEX idx_subscription_plan_version_id (plan_version_id),
  INDEX idx_subscription_currency_id (currency_id),
  INDEX idx_subscription_payment_method_token_id (payment_method_token_id) WHERE payment_method_token_id IS NOT NULL
);
