  CONSTRAINT fk_subscription_cancellation_cancellation_reason_id FOREIGN KEY (cancellation_reason_id) REFERENCES cancellation_reason (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_subscription_cancellation_cancellation_mode_id FOREIGN KEY (cancellation_mode_id) REFERENCES cancellation_mode (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_subscription_cancellation_requested_by_app_user_id FOREIGN KEY (requested_by_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_subscription_cancellation_subscription_id_open (subscription_id) WHERE withdrawn_at IS NULL AND deleted_at IS NULL,
