CREATE TABLE IF NOT EXISTS subscription_entitlement (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  subscription_id UUID NOT NULL,
  entitlement_feature_id UUID NOT NULL,
  limit_value INT8,
  used_count INT8 NOT NULL DEFAULT 0,
  usage_window_start_at TIMESTAMPTZ NOT NULL,
  usage_window_end_at TIMESTAMPTZ NOT NULL,
  CONSTRAINT pk_subscription_entitlement PRIMARY KEY (id),
  CONSTRAINT uq_subscription_entitlement_subscription_feature_window UNIQUE (subscription_id, entitlement_feature_id, usage_window_start_at),
  CONSTRAINT ck_subscription_entitlement_window CHECK (usage_window_end_at >= usage_window_start_at),
  CONSTRAINT ck_subscription_entitlement_used_bounds CHECK (used_count >= 0 AND (limit_value IS NULL OR used_count <= limit_value)),
  CONSTRAINT fk_subscription_entitlement_subscription_id FOREIGN KEY (subscription_id) REFERENCES subscription (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_subscription_entitlement_entitlement_feature_id FOREIGN KEY (entitlement_feature_id) REFERENCES entitlement_feature (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_subscription_entitlement_usage_window_end_at (usage_window_end_at)
);
