CREATE TABLE IF NOT EXISTS consultant_payout (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  payee_app_user_id UUID NOT NULL,
  sourcing_request_id UUID,
  commission_basis_amount DECIMAL(18,4) NOT NULL,
  commission_rate DECIMAL(5,2) NOT NULL,
  commission_amount DECIMAL(18,4) NOT NULL,
  tds_amount DECIMAL(18,4) NOT NULL DEFAULT 0,
  net_payout_amount DECIMAL(18,4) NOT NULL,
  currency_id UUID NOT NULL,
  payout_status_id UUID NOT NULL,
  payout_ref STRING(100),
  scheduled_for_date DATE NOT NULL,
  paid_at TIMESTAMPTZ,
  CONSTRAINT pk_consultant_payout PRIMARY KEY (id),
  CONSTRAINT ck_consultant_payout_math CHECK (net_payout_amount = commission_amount - tds_amount AND tds_amount >= 0 AND commission_amount >= 0),
  CONSTRAINT ck_consultant_payout_rate_range CHECK (commission_rate >= 0 AND commission_rate <= 100),
  CONSTRAINT fk_consultant_payout_payee_app_user_id FOREIGN KEY (payee_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_consultant_payout_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_consultant_payout_payout_status_id FOREIGN KEY (payout_status_id) REFERENCES payout_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_consultant_payout_payee_app_user_id_scheduled_for_date (payee_app_user_id, scheduled_for_date DESC),
  INDEX idx_consultant_payout_sourcing_request_id (sourcing_request_id) WHERE sourcing_request_id IS NOT NULL,
  INDEX idx_consultant_payout_currency_id (currency_id)
);
