CREATE TABLE IF NOT EXISTS invoice (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  organisation_id UUID NOT NULL,
  subscription_id UUID,
  invoice_number_series_id UUID NOT NULL,
  invoice_number INT8,
  invoice_label STRING(40),
  invoice_status_id UUID NOT NULL,
  billing_address_id UUID NOT NULL,
  buyer_tax_registration_id UUID,
  seller_tax_registration_id UUID NOT NULL,
  place_of_supply_state_region_id UUID,
  address_snapshot JSONB NOT NULL,
  currency_id UUID NOT NULL,
  currency_exchange_rate_id UUID,
  subtotal_amount DECIMAL(18,4) NOT NULL,
  tax_amount DECIMAL(18,4) NOT NULL,
  total_amount DECIMAL(18,4) NOT NULL,
  amount_paid DECIMAL(18,4) NOT NULL DEFAULT 0,
  issue_date DATE,
  due_date DATE,
  issued_at TIMESTAMPTZ,
  voided_at TIMESTAMPTZ,
  CONSTRAINT pk_invoice PRIMARY KEY (id),
  CONSTRAINT uq_invoice_series_number UNIQUE (invoice_number_series_id, invoice_number),
  CONSTRAINT uq_invoice_invoice_label UNIQUE (invoice_label),
  CONSTRAINT ck_invoice_totals CHECK (total_amount = subtotal_amount + tax_amount AND subtotal_amount >= 0 AND tax_amount >= 0),
  CONSTRAINT ck_invoice_paid_bounds CHECK (amount_paid >= 0 AND amount_paid <= total_amount),
  CONSTRAINT ck_invoice_number_issued CHECK ((invoice_number IS NULL) = (issued_at IS NULL) AND (invoice_number IS NULL) = (invoice_label IS NULL) AND (invoice_number IS NULL) = (issue_date IS NULL)),
  CONSTRAINT ck_invoice_due_after_issue CHECK (due_date IS NULL OR issue_date IS NULL OR due_date >= issue_date),
  CONSTRAINT fk_invoice_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_invoice_subscription_id FOREIGN KEY (subscription_id) REFERENCES subscription (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_invoice_invoice_number_series_id FOREIGN KEY (invoice_number_series_id) REFERENCES invoice_number_series (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_invoice_invoice_status_id FOREIGN KEY (invoice_status_id) REFERENCES invoice_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_invoice_billing_address_id FOREIGN KEY (billing_address_id) REFERENCES billing_address (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_invoice_buyer_tax_registration_id FOREIGN KEY (buyer_tax_registration_id) REFERENCES tax_registration (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_invoice_seller_tax_registration_id FOREIGN KEY (seller_tax_registration_id) REFERENCES tax_registration (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_invoice_place_of_supply_state_region_id FOREIGN KEY (place_of_supply_state_region_id) REFERENCES state_region (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_invoice_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_invoice_currency_exchange_rate_id FOREIGN KEY (currency_exchange_rate_id) REFERENCES currency_exchange_rate (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_invoice_organisation_id_created_at (organisation_id, created_at DESC),
  INDEX idx_invoice_due_date_open (due_date) WHERE voided_at IS NULL AND due_date IS NOT NULL,
  INDEX idx_invoice_created_at (created_at) USING HASH WITH (bucket_count = 8),
  INDEX idx_invoice_subscription_id (subscription_id) WHERE subscription_id IS NOT NULL,
  INDEX idx_invoice_billing_address_id (billing_address_id),
  INDEX idx_invoice_buyer_tax_registration_id (buyer_tax_registration_id) WHERE buyer_tax_registration_id IS NOT NULL,
  INDEX idx_invoice_seller_tax_registration_id (seller_tax_registration_id),
  INDEX idx_invoice_place_of_supply_state_region_id (place_of_supply_state_region_id) WHERE place_of_supply_state_region_id IS NOT NULL,
  INDEX idx_invoice_currency_id (currency_id),
  INDEX idx_invoice_currency_exchange_rate_id (currency_exchange_rate_id) WHERE currency_exchange_rate_id IS NOT NULL
);
