CREATE TABLE IF NOT EXISTS payment_order (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  organisation_id UUID NOT NULL,
  wallet_id UUID,
  subscription_id UUID,
  credit_pack_id UUID,
  invoice_id UUID,
  payment_purpose_id UUID NOT NULL,
  payment_gateway_id UUID NOT NULL,
  payment_order_status_id UUID NOT NULL,
  amount DECIMAL(18,4) NOT NULL,
  currency_id UUID NOT NULL,
  gateway_order_ref STRING(100),
  idempotency_key STRING(120) NOT NULL,
  created_by_app_user_id UUID,
  expires_at TIMESTAMPTZ,
  paid_at TIMESTAMPTZ,
  failure_code STRING(64),
  CONSTRAINT pk_payment_order PRIMARY KEY (id),
  CONSTRAINT uq_payment_order_idempotency_key UNIQUE (idempotency_key),
  CONSTRAINT uq_payment_order_gateway_order_ref UNIQUE (payment_gateway_id, gateway_order_ref),
  CONSTRAINT ck_payment_order_amount_pos CHECK (amount > 0),
  CONSTRAINT ck_payment_order_paid_after_created CHECK (paid_at IS NULL OR paid_at >= created_at),
  CONSTRAINT fk_payment_order_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_payment_order_wallet_id FOREIGN KEY (wallet_id) REFERENCES wallet (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_payment_order_subscription_id FOREIGN KEY (subscription_id) REFERENCES subscription (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_payment_order_credit_pack_id FOREIGN KEY (credit_pack_id) REFERENCES credit_pack (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_payment_order_invoice_id FOREIGN KEY (invoice_id) REFERENCES invoice (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_payment_order_payment_purpose_id FOREIGN KEY (payment_purpose_id) REFERENCES payment_purpose (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_payment_order_payment_gateway_id FOREIGN KEY (payment_gateway_id) REFERENCES payment_gateway (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_payment_order_payment_order_status_id FOREIGN KEY (payment_order_status_id) REFERENCES payment_order_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_payment_order_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_payment_order_created_by_app_user_id FOREIGN KEY (created_by_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_payment_order_organisation_id_created_at (organisation_id, created_at DESC),
  INDEX idx_payment_order_created_at (created_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_payment_order_payment_order_status_id_expires_at (payment_order_status_id, expires_at) WHERE paid_at IS NULL,
  INDEX idx_payment_order_wallet_id (wallet_id) WHERE wallet_id IS NOT NULL,
  INDEX idx_payment_order_subscription_id (subscription_id) WHERE subscription_id IS NOT NULL,
  INDEX idx_payment_order_credit_pack_id (credit_pack_id) WHERE credit_pack_id IS NOT NULL,
  INDEX idx_payment_order_invoice_id (invoice_id) WHERE invoice_id IS NOT NULL,
  INDEX idx_payment_order_currency_id (currency_id),
  INDEX idx_payment_order_created_by_app_user_id (created_by_app_user_id) WHERE created_by_app_user_id IS NOT NULL
);
