  CONSTRAINT ck_reconciliation_item_resolved_pair CHECK ((resolved_at IS NULL) = (resolved_by_app_user_id IS NULL)),
  CONSTRAINT fk_reconciliation_item_reconciliation_run_id FOREIGN KEY (reconciliation_run_id) REFERENCES reconciliation_run (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_reconciliation_item_payment_order_id FOREIGN KEY (payment_order_id) REFERENCES payment_order (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_reconciliation_item_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_reconciliation_item_match_state_id FOREIGN KEY (match_state_id) REFERENCES match_state (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_reconciliation_item_resolved_by_app_user_id FOREIGN KEY (resolved_by_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_reconciliation_item_reconciliation_run_id_match_state (reconciliation_run_id, match_state_id),
  INDEX idx_reconciliation_item_payment_order_id (payment_order_id) WHERE payment_order_id IS NOT NULL,
  INDEX idx_reconciliation_item_currency_id (currency_id),
  INDEX idx_reconciliation_item_resolved_by_app_user_id (resolved_by_app_user_id) WHERE resolved_by_app_user_id IS NOT NULL
);
