CREATE TABLE IF NOT EXISTS refund (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  payment_order_id UUID NOT NULL,
  refund_status_id UUID NOT NULL,
  refund_reason_id UUID NOT NULL,
  amount DECIMAL(18,4) NOT NULL,
  currency_id UUID NOT NULL,
  credits_clawed_back INT8,
  gateway_refund_ref STRING(100),
  idempotency_key STRING(120) NOT NULL,
  requested_by_app_user_id UUID NOT NULL,
  approved_by_app_user_id UUID,
  processed_at TIMESTAMPTZ,
  CONSTRAINT pk_refund PRIMARY KEY (id),
  CONSTRAINT uq_refund_idempotency_key UNIQUE (idempotency_key),
  CONSTRAINT uq_refund_gateway_refund_ref UNIQUE (gateway_refund_ref),
  CONSTRAINT ck_refund_amount_pos CHECK (amount > 0),
  CONSTRAINT ck_refund_four_eyes CHECK (approved_by_app_user_id IS NULL OR approved_by_app_user_id <> requested_by_app_user_id),
  CONSTRAINT ck_refund_credits_pos CHECK (credits_clawed_back IS NULL OR credits_clawed_back > 0),
  CONSTRAINT fk_refund_payment_order_id FOREIGN KEY (payment_order_id) REFERENCES payment_order (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_refund_refund_status_id FOREIGN KEY (refund_status_id) REFERENCES refund_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_refund_refund_reason_id FOREIGN KEY (refund_reason_id) REFERENCES refund_reason (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_refund_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_refund_requested_by_app_user_id FOREIGN KEY (requested_by_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_refund_approved_by_app_user_id FOREIGN KEY (approved_by_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_refund_payment_order_id (payment_order_id),
  INDEX idx_refund_currency_id (currency_id),
  INDEX idx_refund_requested_by_app_user_id (requested_by_app_user_id),
  INDEX idx_refund_approved_by_app_user_id (approved_by_app_user_id) WHERE approved_by_app_user_id IS NOT NULL
);
