CREATE TABLE IF NOT EXISTS subscription_period (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  subscription_id UUID NOT NULL,
  licence_id UUID NOT NULL,
  sequence_no INT4 NOT NULL,
  period_start_date DATE NOT NULL,
  period_end_date DATE NOT NULL,
  prior_period_id UUID,
  prior_period_end_date DATE,
  subscription_period_status_id UUID NOT NULL,
  plan_version_id UUID NOT NULL,
  billed_amount DECIMAL(18,4) NOT NULL,
  currency_id UUID NOT NULL,
  invoice_id UUID,
  original_period_end_date DATE,
  shortened_at TIMESTAMPTZ,
  CONSTRAINT pk_subscription_period PRIMARY KEY (id),
  CONSTRAINT uq_subscription_period_id_period_end_date UNIQUE (id, period_end_date),
  CONSTRAINT uq_subscription_period_id_licence_end UNIQUE (id, licence_id, period_end_date),
  CONSTRAINT uq_subscription_period_prior_period_id UNIQUE (prior_period_id),
  CONSTRAINT uq_subscription_period_licence_id_sequence_no UNIQUE (licence_id, sequence_no),
  CONSTRAINT ck_subscription_period_dates CHECK (period_start_date <= period_end_date),
  CONSTRAINT ck_subscription_period_chain_pair CHECK ((prior_period_id IS NULL) = (prior_period_end_date IS NULL)),
  CONSTRAINT ck_subscription_period_chain_first CHECK ((sequence_no = 1) = (prior_period_id IS NULL)),
  CONSTRAINT ck_subscription_period_no_overlap_prior CHECK (prior_period_end_date IS NULL OR period_start_date >= prior_period_end_date),
  CONSTRAINT ck_subscription_period_not_self_prior CHECK (prior_period_id IS NULL OR prior_period_id <> id),
  CONSTRAINT ck_subscription_period_shorten_pair CHECK ((original_period_end_date IS NULL) = (shortened_at IS NULL) AND (original_period_end_date IS NULL OR original_period_end_date >= period_end_date)),
  CONSTRAINT ck_subscription_period_amount_nonneg CHECK (billed_amount >= 0),
  CONSTRAINT fk_subscription_period_subscription_id FOREIGN KEY (subscription_id) REFERENCES subscription (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_subscription_period_subscription_period_status_id FOREIGN KEY (subscription_period_status_id) REFERENCES subscription_period_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_subscription_period_plan_version_id FOREIGN KEY (plan_version_id) REFERENCES plan_version (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_subscription_period_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_subscription_period_invoice_id FOREIGN KEY (invoice_id) REFERENCES invoice (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_subscription_period_prior_period FOREIGN KEY (prior_period_id, licence_id, prior_period_end_date) REFERENCES subscription_period (id, licence_id, period_end_date) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_subscription_period_subscription_licence FOREIGN KEY (subscription_id, licence_id) REFERENCES subscription (id, licence_id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_subscription_period_licence_id_first (licence_id) WHERE prior_period_id IS NULL,
  INDEX idx_subscription_period_subscription_id_start (subscription_id, period_start_date DESC),
  INDEX idx_subscription_period_period_end_date (period_end_date),
  INDEX idx_subscription_period_plan_version_id (plan_version_id),
  INDEX idx_subscription_period_currency_id (currency_id),
  INDEX idx_subscription_period_invoice_id (invoice_id) WHERE invoice_id IS NOT NULL
);
