  CONSTRAINT fk_subscription_renewal_attempt_subscription_id FOREIGN KEY (subscription_id) REFERENCES subscription (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_subscription_renewal_attempt_renewal_outcome_id FOREIGN KEY (renewal_outcome_id) REFERENCES renewal_outcome (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
