  CONSTRAINT ck_coupon_redemption_payload CHECK ((discount_amount IS NULL) <> (bonus_credits_granted IS NULL)),
  CONSTRAINT fk_coupon_redemption_coupon_id FOREIGN KEY (coupon_id) REFERENCES coupon (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_coupon_redemption_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_coupon_redemption_payment_order_id FOREIGN KEY (payment_order_id) REFERENCES payment_order (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_coupon_redemption_invoice_id FOREIGN KEY (invoice_id) REFERENCES invoice (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_coupon_redemption_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_coupon_redemption_coupon_id_organisation (coupon_id, organisation_id),
  INDEX idx_coupon_redemption_organisation_id (organisation_id),
  INDEX idx_coupon_redemption_payment_order_id (payment_order_id) WHERE payment_order_id IS NOT NULL,
  INDEX idx_coupon_redemption_invoice_id (invoice_id) WHERE invoice_id IS NOT NULL,
  INDEX idx_coupon_redemption_currency_id (currency_id)
);
