CREATE TABLE IF NOT EXISTS credit_note (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  invoice_id UUID NOT NULL,
  invoice_number_series_id UUID NOT NULL,
  credit_note_number INT8 NOT NULL,
  credit_note_label STRING(40) NOT NULL,
  credit_note_reason_id UUID NOT NULL,
  refund_id UUID,
  subtotal_amount DECIMAL(18,4) NOT NULL,
  tax_amount DECIMAL(18,4) NOT NULL,
  total_amount DECIMAL(18,4) NOT NULL,
  currency_id UUID NOT NULL,
  issue_date DATE NOT NULL,
  CONSTRAINT pk_credit_note PRIMARY KEY (id),
  CONSTRAINT uq_credit_note_series_number UNIQUE (invoice_number_series_id, credit_note_number),
  CONSTRAINT uq_credit_note_credit_note_label UNIQUE (credit_note_label),
  CONSTRAINT ck_credit_note_totals CHECK (total_amount = subtotal_amount + tax_amount AND total_amount > 0 AND subtotal_amount >= 0 AND tax_amount >= 0),
  CONSTRAINT fk_credit_note_invoice_id FOREIGN KEY (invoice_id) REFERENCES invoice (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_credit_note_invoice_number_series_id FOREIGN KEY (invoice_number_series_id) REFERENCES invoice_number_series (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_credit_note_credit_note_reason_id FOREIGN KEY (credit_note_reason_id) REFERENCES credit_note_reason (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_credit_note_refund_id FOREIGN KEY (refund_id) REFERENCES refund (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_credit_note_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_credit_note_invoice_id (invoice_id),
  INDEX idx_credit_note_refund_id (refund_id) WHERE refund_id IS NOT NULL,
  INDEX idx_credit_note_currency_id (currency_id)
);
