CREATE TABLE IF NOT EXISTS invoice_line (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  invoice_id UUID NOT NULL,
  line_no INT4 NOT NULL,
  invoice_line_kind_id UUID NOT NULL,
  description STRING(300) NOT NULL,
  hsn_sac_code STRING(10),
  quantity INT4 NOT NULL,
  unit_price DECIMAL(18,4) NOT NULL,
  net_amount DECIMAL(18,4) NOT NULL,
  currency_id UUID NOT NULL,
  subscription_period_id UUID,
  credit_pack_id UUID,
  CONSTRAINT pk_invoice_line PRIMARY KEY (id),
  CONSTRAINT uq_invoice_line_invoice_id_line_no UNIQUE (invoice_id, line_no),
  CONSTRAINT ck_invoice_line_qty_pos CHECK (quantity > 0),
  CONSTRAINT ck_invoice_line_net_math CHECK (net_amount = quantity * unit_price),
  CONSTRAINT fk_invoice_line_invoice_id FOREIGN KEY (invoice_id) REFERENCES invoice (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_invoice_line_invoice_line_kind_id FOREIGN KEY (invoice_line_kind_id) REFERENCES invoice_line_kind (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_invoice_line_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_invoice_line_subscription_period_id FOREIGN KEY (subscription_period_id) REFERENCES subscription_period (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_invoice_line_credit_pack_id FOREIGN KEY (credit_pack_id) REFERENCES credit_pack (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_invoice_line_currency_id (currency_id),
  INDEX idx_invoice_line_subscription_period_id (subscription_period_id) WHERE subscription_period_id IS NOT NULL,
  INDEX idx_invoice_line_credit_pack_id (credit_pack_id) WHERE credit_pack_id IS NOT NULL
);
