CREATE TABLE IF NOT EXISTS invoice_tax_line (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  invoice_line_id UUID NOT NULL,
  tax_component_id UUID NOT NULL,
  tax_rate_id UUID NOT NULL,
  rate_percent DECIMAL(5,2) NOT NULL,
  taxable_amount DECIMAL(18,4) NOT NULL,
  tax_amount DECIMAL(18,4) NOT NULL,
  currency_id UUID NOT NULL,
  CONSTRAINT pk_invoice_tax_line PRIMARY KEY (id),
  CONSTRAINT uq_invoice_tax_line_line_component UNIQUE (invoice_line_id, tax_component_id),
  CONSTRAINT ck_invoice_tax_line_rate_range CHECK (rate_percent >= 0 AND rate_percent <= 100),
  CONSTRAINT ck_invoice_tax_line_tax_math CHECK (abs(tax_amount - taxable_amount * rate_percent / 100) <= 0.01),
  CONSTRAINT fk_invoice_tax_line_invoice_line_id FOREIGN KEY (invoice_line_id) REFERENCES invoice_line (id) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT fk_invoice_tax_line_tax_component_id FOREIGN KEY (tax_component_id) REFERENCES tax_component (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_invoice_tax_line_tax_rate_id FOREIGN KEY (tax_rate_id) REFERENCES tax_rate (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_invoice_tax_line_currency_id FOREIGN KEY (currency_id) REFERENCES currency (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_invoice_tax_line_tax_rate_id (tax_rate_id),
  INDEX idx_invoice_tax_line_currency_id (currency_id)
);
