CREATE TABLE IF NOT EXISTS payment_attempt (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  payment_order_id UUID NOT NULL,
  attempt_no INT4 NOT NULL,
  payment_attempt_status_id UUID NOT NULL,
  payment_method_kind_id UUID NOT NULL,
  payment_method_token_id UUID,
  gateway_payment_ref STRING(100),
  error_code STRING(64),
  error_message STRING(300),
  initiated_at TIMESTAMPTZ NOT NULL,
  completed_at TIMESTAMPTZ,
  CONSTRAINT pk_payment_attempt PRIMARY KEY (id),
  CONSTRAINT uq_payment_attempt_payment_order_id_attempt_no UNIQUE (payment_order_id, attempt_no),
  CONSTRAINT ck_payment_attempt_attempt_pos CHECK (attempt_no > 0 AND (completed_at IS NULL OR completed_at >= initiated_at)),
  CONSTRAINT fk_payment_attempt_payment_order_id FOREIGN KEY (payment_order_id) REFERENCES payment_order (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_payment_attempt_payment_attempt_status_id FOREIGN KEY (payment_attempt_status_id) REFERENCES payment_attempt_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_payment_attempt_payment_method_kind_id FOREIGN KEY (payment_method_kind_id) REFERENCES payment_method_kind (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_payment_attempt_payment_method_token_id FOREIGN KEY (payment_method_token_id) REFERENCES payment_method_token (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_payment_attempt_gateway_payment_ref_set (gateway_payment_ref) WHERE gateway_payment_ref IS NOT NULL,
  INDEX idx_payment_attempt_initiated_at (initiated_at) USING HASH WITH (bucket_count = 8),
  INDEX idx_payment_attempt_payment_method_token_id (payment_method_token_id) WHERE payment_method_token_id IS NOT NULL
);
-- @@
CREATE TABLE IF NOT EXISTS payment_event (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  payment_gateway_id UUID NOT NULL,
  gateway_event_ref STRING(120) NOT NULL,
  event_type STRING(64) NOT NULL,
  payment_order_id UUID,
  payload JSONB NOT NULL,
  signature_valid BOOL NOT NULL DEFAULT false,
  received_at TIMESTAMPTZ NOT NULL,
  CONSTRAINT pk_payment_event PRIMARY KEY (id),
  CONSTRAINT uq_payment_event_gateway_event_ref UNIQUE (payment_gateway_id, gateway_event_ref),
  CONSTRAINT fk_payment_event_payment_gateway_id FOREIGN KEY (payment_gateway_id) REFERENCES payment_gateway (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_payment_event_payment_order_id FOREIGN KEY (payment_order_id) REFERENCES payment_order (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_payment_event_received_at (received_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_payment_event_payment_order_id_received_at (payment_order_id, received_at) WHERE payment_order_id IS NOT NULL
) WITH (ttl_expiration_expression = '(received_at + INTERVAL ''540 days'')', ttl_job_cron = '@daily');
-- @@
CREATE TABLE IF NOT EXISTS payment_event_outcome (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  payment_event_id UUID,
  webhook_outcome_id UUID NOT NULL,
  processed_at TIMESTAMPTZ NOT NULL,
  detail STRING(300),
  CONSTRAINT pk_payment_event_outcome PRIMARY KEY (id),
  CONSTRAINT fk_payment_event_outcome_payment_event_id FOREIGN KEY (payment_event_id) REFERENCES payment_event (id) ON DELETE SET NULL ON UPDATE RESTRICT,
  CONSTRAINT fk_payment_event_outcome_webhook_outcome_id FOREIGN KEY (webhook_outcome_id) REFERENCES webhook_outcome (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_payment_event_outcome_payment_event_id_processed_at (payment_event_id, processed_at),
  INDEX idx_payment_event_outcome_processed_at (processed_at) USING HASH WITH (bucket_count = 16)
);
