CREATE TABLE IF NOT EXISTS profile_download (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  organisation_id UUID NOT NULL,
  actor_app_user_id UUID NOT NULL,
  candidate_profile_id UUID NOT NULL,
  resume_id UUID,
  download_kind_id UUID NOT NULL,
  download_source_id UUID NOT NULL,
  device_session_id UUID,
  wallet_ledger_entry_id UUID,
  subscription_entitlement_id UUID,
  prior_profile_download_id UUID,
  credits_charged INT4 NOT NULL,
  downloaded_at TIMESTAMPTZ NOT NULL,
  idempotency_key STRING(120) NOT NULL,
  CONSTRAINT pk_profile_download PRIMARY KEY (id),
  CONSTRAINT uq_profile_download_idempotency_key UNIQUE (idempotency_key),
  CONSTRAINT uq_profile_download_wallet_ledger_entry_id UNIQUE (wallet_ledger_entry_id),
  CONSTRAINT ck_profile_download_payer_exactly_one CHECK (num_nonnulls(wallet_ledger_entry_id, subscription_entitlement_id, prior_profile_download_id) = 1),
  CONSTRAINT ck_profile_download_credits_consistent CHECK ((credits_charged > 0) = (wallet_ledger_entry_id IS NOT NULL) AND credits_charged >= 0),
  CONSTRAINT fk_profile_download_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_profile_download_actor_app_user_id FOREIGN KEY (actor_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_profile_download_candidate_profile_id FOREIGN KEY (candidate_profile_id) REFERENCES candidate_profile (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_profile_download_resume_id FOREIGN KEY (resume_id) REFERENCES resume (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_profile_download_download_kind_id FOREIGN KEY (download_kind_id) REFERENCES download_kind (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_profile_download_download_source_id FOREIGN KEY (download_source_id) REFERENCES download_source (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_profile_download_subscription_entitlement_id FOREIGN KEY (subscription_entitlement_id) REFERENCES subscription_entitlement (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_profile_download_prior_profile_download_id FOREIGN KEY (prior_profile_download_id) REFERENCES profile_download (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_profile_download_organisation_id_candidate_profile_id_downloaded_at (organisation_id, candidate_profile_id, downloaded_at DESC),
  INDEX idx_profile_download_actor_app_user_id_downloaded_at (actor_app_user_id, downloaded_at DESC),
  INDEX idx_profile_download_downloaded_at (downloaded_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_profile_download_candidate_profile_id (candidate_profile_id),
  INDEX idx_profile_download_resume_id (resume_id) WHERE resume_id IS NOT NULL,
  INDEX idx_profile_download_device_session_id (device_session_id) WHERE device_session_id IS NOT NULL,
  INDEX idx_profile_download_subscription_entitlement_id (subscription_entitlement_id) WHERE subscription_entitlement_id IS NOT NULL,
  INDEX idx_profile_download_prior_profile_download_id (prior_profile_download_id) WHERE prior_profile_download_id IS NOT NULL
);
