CREATE TABLE IF NOT EXISTS wallet_bucket_consumption (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  wallet_ledger_entry_id UUID NOT NULL,
  wallet_expiry_bucket_id UUID NOT NULL,
  credits INT8 NOT NULL,
  CONSTRAINT pk_wallet_bucket_consumption PRIMARY KEY (id),
  CONSTRAINT uq_wallet_bucket_consumption_entry_bucket UNIQUE (wallet_ledger_entry_id, wallet_expiry_bucket_id),
  CONSTRAINT ck_wallet_bucket_consumption_credits_nonzero CHECK (credits <> 0),
  INDEX idx_wallet_bucket_consumption_wallet_expiry_bucket_id (wallet_expiry_bucket_id),
  INDEX idx_wallet_bucket_consumption_created_at (created_at) USING HASH WITH (bucket_count = 16)
);
-- @@
CREATE TABLE IF NOT EXISTS wallet_expiry_bucket (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  wallet_id UUID NOT NULL,
  source_wallet_ledger_entry_id UUID NOT NULL,
  credits_granted INT8 NOT NULL,
  credits_remaining INT8 NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  fully_consumed_at TIMESTAMPTZ,
  CONSTRAINT pk_wallet_expiry_bucket PRIMARY KEY (id),
  CONSTRAINT uq_wallet_expiry_bucket_source_wallet_ledger_entry_id UNIQUE (source_wallet_ledger_entry_id),
  CONSTRAINT ck_wallet_expiry_bucket_remaining_bounds CHECK (credits_remaining >= 0 AND credits_remaining <= credits_granted AND credits_granted > 0),
  CONSTRAINT fk_wallet_expiry_bucket_wallet_id FOREIGN KEY (wallet_id) REFERENCES wallet (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_wallet_expiry_bucket_wallet_id_expires_at (wallet_id, expires_at) WHERE credits_remaining > 0,
  INDEX idx_wallet_expiry_bucket_expires_at (expires_at) USING HASH WITH (bucket_count = 8) WHERE credits_remaining > 0
);
-- @@
CREATE TABLE IF NOT EXISTS wallet_ledger_entry (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  wallet_id UUID NOT NULL,
  sequence_no INT8 NOT NULL,
  prev_sequence_no INT8,
  ledger_entry_type_id UUID NOT NULL,
  credits_delta INT8 NOT NULL,
  is_debit BOOL NOT NULL DEFAULT false,
  balance_after INT8 NOT NULL,
  idempotency_key STRING(120) NOT NULL,
  actor_app_user_id UUID,
  reverses_wallet_ledger_entry_id UUID,
  has_fk_reference BOOL NOT NULL DEFAULT true,
  payment_order_id UUID,
  refund_id UUID,
  outreach_batch_id UUID,
  job_requirement_id UUID,
  coupon_redemption_id UUID,
  wallet_expiry_bucket_id UUID,
  adjustment_note STRING(300),
  prev_hash BYTES,
  row_hash BYTES NOT NULL,
  CONSTRAINT pk_wallet_ledger_entry PRIMARY KEY (id),
  CONSTRAINT uq_wallet_ledger_entry_wallet_id_sequence_no UNIQUE (wallet_id, sequence_no),
  CONSTRAINT uq_wallet_ledger_entry_idempotency_key UNIQUE (idempotency_key),
  CONSTRAINT uq_wallet_ledger_entry_reverses_wallet_ledger_entry_id UNIQUE (reverses_wallet_ledger_entry_id),
  CONSTRAINT ck_wallet_ledger_entry_delta_nonzero CHECK (credits_delta <> 0),
  CONSTRAINT ck_wallet_ledger_entry_sign_flag CHECK ((is_debit AND credits_delta < 0) OR ((NOT is_debit) AND credits_delta > 0)),
  CONSTRAINT ck_wallet_ledger_entry_balance_nonneg CHECK (balance_after >= 0),
  CONSTRAINT ck_wallet_ledger_entry_seq_pos CHECK (sequence_no > 0 AND (sequence_no = 1) = (prev_sequence_no IS NULL) AND (prev_sequence_no IS NULL OR prev_sequence_no = sequence_no - 1)),
  CONSTRAINT ck_wallet_ledger_entry_hash_chain CHECK ((sequence_no = 1) = (prev_hash IS NULL)),
  CONSTRAINT ck_wallet_ledger_entry_single_reference CHECK (num_nonnulls(payment_order_id, refund_id, outreach_batch_id, job_requirement_id, coupon_redemption_id, wallet_expiry_bucket_id, reverses_wallet_ledger_entry_id) = CASE WHEN has_fk_reference THEN 1 ELSE 0 END),
  CONSTRAINT fk_wallet_ledger_entry_wallet_id FOREIGN KEY (wallet_id) REFERENCES wallet (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_wallet_ledger_entry_ledger_entry_type_id FOREIGN KEY (ledger_entry_type_id) REFERENCES ledger_entry_type (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_wallet_ledger_entry_actor_app_user_id FOREIGN KEY (actor_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_wallet_ledger_entry_reverses_wallet_ledger_entry_id FOREIGN KEY (reverses_wallet_ledger_entry_id) REFERENCES wallet_ledger_entry (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_wallet_ledger_entry_payment_order_id FOREIGN KEY (payment_order_id) REFERENCES payment_order (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_wallet_ledger_entry_refund_id FOREIGN KEY (refund_id) REFERENCES refund (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_wallet_ledger_entry_job_requirement_id FOREIGN KEY (job_requirement_id) REFERENCES job_requirement (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_wallet_ledger_entry_coupon_redemption_id FOREIGN KEY (coupon_redemption_id) REFERENCES coupon_redemption (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_wallet_ledger_entry_wallet_expiry_bucket_id FOREIGN KEY (wallet_expiry_bucket_id) REFERENCES wallet_expiry_bucket (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_wallet_ledger_entry_prev_entry FOREIGN KEY (wallet_id, prev_sequence_no) REFERENCES wallet_ledger_entry (wallet_id, sequence_no) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_wallet_ledger_entry_created_at (created_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_wallet_ledger_entry_actor_app_user_id_created_at (actor_app_user_id, created_at DESC) WHERE actor_app_user_id IS NOT NULL,
  INDEX idx_wallet_ledger_entry_payment_order_id (payment_order_id) WHERE payment_order_id IS NOT NULL,
  INDEX idx_wallet_ledger_entry_refund_id (refund_id) WHERE refund_id IS NOT NULL,
  INDEX idx_wallet_ledger_entry_outreach_batch_id (outreach_batch_id) WHERE outreach_batch_id IS NOT NULL,
  INDEX idx_wallet_ledger_entry_job_requirement_id (job_requirement_id) WHERE job_requirement_id IS NOT NULL,
  INDEX idx_wallet_ledger_entry_coupon_redemption_id (coupon_redemption_id) WHERE coupon_redemption_id IS NOT NULL,
  INDEX idx_wallet_ledger_entry_wallet_expiry_bucket_id (wallet_expiry_bucket_id) WHERE wallet_expiry_bucket_id IS NOT NULL
